/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const contentBlocks = api.data.ace_fetch_content_blocks.output;
    if (contentBlocks) {
        var res = contentBlocks
            .filter(function(contentBlock) {
                return contentBlock.name === "Page Header BreadCrumbs";
            });
        if (res.length > 0 && res[0].props_details.breadcrumbs.length > 0) return 0;
    }
    return 1;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {

    const contentBlocks = api.data.ace_fetch_content_blocks.output;
    if (contentBlocks) {
        var res = contentBlocks
            .filter(function(contentBlock) {
                return contentBlock.name === "Page Header BreadCrumbs";
            });
        if (res.length > 0) return res[0].props_details.breadcrumbs;
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    let channel_type = api.context.props.channelType;

    if (channel_type == 'messenger')
        return 'Integrate Messenger with self configured bot';
    else if (channel_type == 'line')
        return 'Integrate Line with self configured bot';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  var url = '';
  if (api.context.props.channelType == 'messenger')
    url = '/api/now/v1/context_doc_url/va-fb-messenger-integration';
  else if(api.context.props.channelType == 'line')
    url = '/api/now/v1/context_doc_url/va-line-integration';    

	  return `<p>To learn more, refer the <a href='` + url + `' target='_blank' style='cursor:pointer;text-decoration:none;color: rgb(1, 119, 142);'>step-by-step guide.</a><p>`;
}

